):not(:has(
.msg-reply-block,
.msg-reply-block-detached,
[class*="reply"],
[class*="quote"],
[class*="avatar"],
p,
.msg-text,
.text-content,
.msg-history-card, 
.msg-loc-card,     
[class*="voice"]:not([class*="videocall"],[class*="voice-call"],
[class*="voicecall"],[class*="call-card"])
))::after{
  display:none!important;
  content:none!important;
  background:transparent none!important;
  border:0 none!important;
  box-shadow:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  filter:none!important;
  opacity:0!important;
}
.msg-content-stack:not(:has(.msg-reply-block-detached img)) :is(.bubble-me-custom, .bubble-them-custom):has(:is(
  .msg-transfer-card, .msg-videocall-card, .msg-sim-card, .gift-ig-container, 
  img, .msg-image-wrapper img, .sticker-container img, [class*="sticker"] img, [class*="emoji"] img, [class*="表情"] img
)):not(:has(.msg-text, p, .voice-msg)) {
   filter: none;
   background: transparent !important;
